// Fonction de croisement
void croisement(Tsolution P1, Tsolution P2, Tsolution *E, int nbTaches) {
    int pointDeCroisement = rand() % nbTaches;
    int i, j, positionE = pointDeCroisement;

    // Copie de la première partie du père dans l'enfant
    for (i = 0; i < pointDeCroisement; i++) {
        E->table[i] = P1.table[i];
    }

    // On complète la deuxième partie en vérifiant que l'élément n'est pas déjà dans l'enfant
    for (i = 0; i < nbTaches; i++) {
        int existeDeja = 0;

        for (j = 0; j < pointDeCroisement; j++) {
            if (P2.table[i] == E->table[j]) {
